theorem sensitivityIndicator_sq {n : ℕ} {f : Cube n → ℝ}
    (hf : ∀ x, f x = -1 ∨ f x = 1) (i : Fin n) (x : Cube n) :
    sensitivityIndicator f i x ^ 2 = sensitivityIndicator f i x

theorem sensitivityIndicator_zero_or_one {n : ℕ} {f : Cube n → ℝ}
    (hf : ∀ x, f x = -1 ∨ f x = 1) (i : Fin n) (x : Cube n) :
    sensitivityIndicator f i x = 0 ∨ sensitivityIndicator f i x = 1

theorem sensitivity_second_moment {n : ℕ} {f : Cube n → ℝ}
    (hf : ∀ x, f x = -1 ∨ f x = 1) (hb : IsBent f) :
    mean (fun x => sensitivity f x ^ 2) = (n : ℝ) * (n + 1) / 4

theorem no_sign_reversing_translation {n : ℕ} {f : Cube n → ℝ}
    (hb : IsBent f) (v : Cube n) :
    ¬ (∀ x, f (translate v x) = -f x)

theorem posSemidef_blockDiagonal {A : Matrix ι ι ℝ} {B : Matrix κ κ ℝ}
    (hA : A.PosSemidef) (hB : B.PosSemidef) :
    (Matrix.fromBlocks A 0 0 B).PosSemidef

theorem trace_mul_le_traceNorm {A Q : Matrix ι ι ℝ}
    (hA : A.IsHermitian) (hQ : OrderContraction Q) :
    (Q * A).trace ≤ traceNorm A

theorem matrix_eigenvalues_mono {A B : Matrix ι ι ℝ}
    (hA : A.IsHermitian) (hB : B.IsHermitian) (hAB : A ≤ B)
    (k : Fin (Fintype.card ι)) : hA.eigenvalues₀ k ≤ hB.eigenvalues₀ k

theorem ordered_eigenvalue_distance_le_traceNorm {A B : Matrix ι ι ℝ}
    (hA : A.IsHermitian) (hB : B.IsHermitian) :
    (∑ j, |hA.eigenvalues₀ j - hB.eigenvalues₀ j|) ≤ traceNorm (A - B)

theorem sum_positive_eigenvalue_differences_le {A B : Matrix ι ι ℝ}
    (hA : A.IsHermitian) (hB : B.IsHermitian) :
    (∑ j, max (hA.eigenvalues₀ j - hB.eigenvalues₀ j) 0) ≤ ((A - B)⁺).trace

theorem anticommuting_trace_identity {F Q : Matrix ι ι ℝ}
    (hQ : F * Q * F = -Q) (K : Matrix ι ι ℝ) :
    (Q * (K - F * K * F)).trace = 2 * (K * Q).trace

theorem operatorNorm_quadratic_abs_le {Q : Matrix ι ι ℝ}
    (hQ : ‖Matrix.toEuclideanCLM (𝕜 := ℝ) (n := ι) Q‖ ≤ 1) (v : ι → ℝ) :
    |v ⬝ᵥ Q *ᵥ v| ≤ v ⬝ᵥ v

theorem orderContraction_eigenvalue_abs_le {Q : Matrix ι ι ℝ}
    (hQ : OrderContraction Q) (i : ι) :
    |(orderContraction_isHermitian hQ).eigenvalues i| ≤ 1

theorem orderContraction_half_sub {Q R : Matrix ι ι ℝ}
    (hQ : OrderContraction Q) (hR : OrderContraction R) :
    OrderContraction ((1 / 2 : ℝ) • (Q - R))

theorem orderContraction_reflection_conjugate {F Q : Matrix ι ι ℝ}
    (hF : F.IsHermitian) (hFsq : F * F = 1) (hQ : OrderContraction Q) :
    OrderContraction (F * Q * F)

@[simp] theorem productKernel_singleton (κ : (i : ι) → Kernel (E i) Bool)
    [∀ i, IsMarkovKernel (κ i)] (y : (i : ι) → E i) (b : ι → Bool) :
    productKernel κ y {b} = ∏ i, κ i (y i) {b i}

theorem convex_mean {Ω : Type*} [Fintype Ω] [Nonempty Ω] {Φ : ℝ → ℝ} {a b : ℝ}
    (hΦ : ConvexOn ℝ (Icc a b) Φ) (u : Ω → ℝ) (hu : ∀ x, u x ∈ Icc a b) :
    Φ (mean u) ≤ mean (fun x => Φ (u x))

theorem anticommuting_trace_identity {F Q : Matrix ι ι ℂ}
    (hQ : F * Q * F = -Q) (K : Matrix ι ι ℂ) :
    realTrace (Q * (K - F * K * F)) = 2 * realTrace (K * Q)

theorem anticommuting_trace_maximum {K F : Matrix ι ι ℂ}
    (hK : K.IsHermitian) (hF : F.IsHermitian) (hFsq : F * F = 1) :
    IsGreatest {t : ℝ | ∃ Q : Matrix ι ι ℂ,
      Q.IsHermitian ∧ ‖Q‖ ≤ 1 ∧ F * Q * F = -Q ∧ t = realTrace (K * Q)}
      (traceNorm (K - F * K * F) / 2)

theorem norm_reflection_conjugate {F : Matrix ι ι ℂ}
    (hF : F.IsHermitian) (hFsq : F * F = 1) (A : Matrix ι ι ℂ) :
    ‖F * A * F‖ = ‖A‖

theorem realTrace_hermitian_product {K Q : Matrix ι ι ℂ}
    (hK : K.IsHermitian) (hQ : Q.IsHermitian) :
    (realTrace (K * Q) : ℂ) = (K * Q).trace

